"""NeuroDetect MRI inference helper (generated by NeuroDetect_MRI_Model_Training.ipynb).
Research prototype - not for clinical use."""
import numpy as np
from PIL import Image

_RESAMPLE = getattr(Image, "Resampling", Image).BILINEAR

def load_and_preprocess_image(image_path, img_size=224):
    """Open one 2D MRI image, convert to 3-channel RGB, resize to (img_size, img_size).
    Returns a uint8 array of shape (img_size, img_size, 3) with raw 0-255 values.
    Intensity normalisation is performed INSIDE the saved Keras model."""
    with Image.open(image_path) as im:
        im = im.convert("RGB")
        im = im.resize((img_size, img_size), _RESAMPLE)
        return np.asarray(im, dtype=np.uint8)

import json

MODEL_NAME = 'NeuroDetect-MRI-EfficientNetB0'
MODEL_VERSION = '1.0.0'
DISCLAIMER = 'Research prototype for academic use only. Not a medical device and not clinically validated. Outputs must not be used for diagnosis or clinical decision-making. Class labels are inherited from a public dataset and the binary dementia grouping is not a clinical diagnostic definition.'
NON_DEMENTED_LABEL = "Non-Demented"
PROBABILITY_KEYS = {
    "Non-Demented": "probability_non_demented",
    "Very Mildly Demented": "probability_very_mild",
    "Mildly Demented": "probability_mild",
    "Moderately Demented": "probability_moderate",
}


def predict_mri(image_path, model, class_indices, img_size=None):
    """
    Load and preprocess one 2D MRI image.
    Return four class probabilities,
    predicted class, and binary grouping.

    image_path    : path to a 2D MRI image (JPEG/PNG/...)
    model         : tf.keras model loaded from mri_model.keras (normalisation is inside the model)
    class_indices : dict loaded from class_indices.json, e.g. {"Non-Demented": 0, ...}
    Returns a JSON-serialisable dict.
    """
    if img_size is None:
        img_size = int(model.input_shape[1])
    arr = load_and_preprocess_image(image_path, img_size)            # uint8, (H, W, 3), raw 0-255
    batch = np.expand_dims(arr.astype("float32"), axis=0)
    probs = np.asarray(model.predict(batch, verbose=0))[0].astype("float64")

    idx_to_class = {int(v): k for k, v in class_indices.items()}
    if len(probs) != len(idx_to_class):
        raise ValueError("Model output size does not match class_indices.json")
    by_class = {idx_to_class[i]: float(probs[i]) for i in range(len(probs))}
    pred_idx = int(np.argmax(probs))

    p_no = by_class[NON_DEMENTED_LABEL]
    p_dem = float(sum(v for k, v in by_class.items() if k != NON_DEMENTED_LABEL))
    result = {
        "predicted_class": idx_to_class[pred_idx],
        "predicted_class_index": pred_idx,
    }
    for cls, key in PROBABILITY_KEYS.items():
        result[key] = by_class[cls]
    result.update({
        "binary_prediction": "Dementia" if p_dem >= 0.5 else "No Dementia",
        "binary_probabilities": {"no_dementia": p_no, "dementia": p_dem},
        "model_name": MODEL_NAME,
        "model_version": MODEL_VERSION,
        "disclaimer": DISCLAIMER,
    })
    return result


if __name__ == "__main__":
    import sys
    import tensorflow as tf
    here = __import__("pathlib").Path(__file__).resolve().parent
    mdl = tf.keras.models.load_model(here / "mri_model.keras", compile=False)
    cls = json.load(open(here / "class_indices.json"))
    print(json.dumps(predict_mri(sys.argv[1], mdl, cls), indent=2))
